    _get_ptx_module().function("matmul_kernel")
class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented via a custom PTX kernel using split-K parallelism to better utilize the GPU
    when the reduction dimension K is very large relative to M and N.
