        assert K == K2
        # Zero-initialize C because partial sums from each split-K slice are
        # accumulated into it via atomic adds.
        C = torch.zeros((M, N), dtype=torch.float32, device=A.device)
        module = _get_ptx_module()
        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y
        # Split the large K dimension across multiple thread blocks to expose
        # more parallelism (K is far larger than M/N in this workload).
        SPLIT_K = 16
        grid_z = SPLIT_K
        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(M), u32(N), u32(K), u32(SPLIT_K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

